  --mvu-accent: #a89f8d;    /* 默认强调 */
  --mvu-success: #94a684;   /* 正面/达成 */
  --mvu-warning: #d4a373;   /* 警告/注意 */
  --mvu-danger: #bc8a8a;    /* 危险/负面 */

