  padding-bottom: 2px;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* 变量行：两端对齐，信息密集 */
.stat-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.85rem;
  line-height: 1.4;
  margin-bottom: 2px;
}

.label {
  color: var(--text-gray);
  font-size: 0.8rem;
}

.value {
  font-weight: 500;
  color: var(--text-main);
}

/* 特殊数值着色 */
.value-num {
  color: var(--accent-main);
  font-variant-numeric: tabular-nums;
}

/* 更新时的闪烁动画 */
.flash-update {
  animation: flash 0.6s ease-out;
}

@keyframes flash {
  0% { background-color: var(--accent-soft); }
  100% { background-color: transparent; }
}

/* 加载状态 */
.loading-state {
  grid-column: 1 / -1;
  text-align: center;
  padding: 20px;
  color: var(--text-gray);
  font-style: italic;
  animation: breathe 1.5s infinite ease-in-out;
}

@keyframes breathe {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}
