            if (typeof val === "object" && val !== null) {
                renderVarTree(val, $container, level + 1);
            } else {
                /* 这里可根据需要动态创建 DOM 节点 */
            }
        }
    }
}

/* === Step 7: 事件绑定+入口 === */
async function init() {
  /* 异步等待 MVU 核心系统初始化完成，防止首屏加载时因数据未就绪导致的空白 */
  await waitGlobalInitialized('Mvu');

  /* 执行首次渲染：读取当前变量并填充至 DOM */
  const currentData = loadVars();
  renderVars(currentData);

  /* 监听变量初始化事件：当新存档加载或变量重置时触发 */
  eventOn(Mvu.events.VARIABLE_INITIALIZED, () => {
    const data = loadVars();
    renderVars(data);
  });

  /* 监听变量更新结束事件：当 AI 输出 <JSONPatch> 并完成变量修改后触发 */
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
    const data = loadVars();
    renderVars(data);
  });
}

/* 使用全局异常捕获函数包裹 init，并注入到酒馆助手的执行序列中 */
$(errorCatched(init));
})();
  </script>
