/* 终端主容器：毛玻璃质感与以太边框 */
#observer-terminal {
    width: 100%;
    background: var(--bg-glass);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(163, 102, 255, 0.4);
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.5), inset 0 0 10px rgba(163, 102, 255, 0.2);
    padding: 10px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 8px;
    font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', monospace;
    color: #e0e0e0;
    overflow: hidden;
    position: relative;
}

/* 三段式网格布局 */
.terminal-main-grid {
    display: grid;
    grid-template-columns: 1fr 1.2fr 1fr;
    gap: 12px;
    z-index: 2;
}

/* 分组面板通用样式 */
.stat-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
    background: rgba(255, 255, 255, 0.03);
    padding: 6px;
    border-left: 2px solid var(--samsara-color);
}

.stat-group.center-panel {
    border-left: none;
    border-top: 2px solid var(--ether-color);
    align-items: center;
    background: rgba(163, 102, 255, 0.05);
}

.stat-group.right-panel {
    border-left: none;
    border-right: 2px solid var(--entropy-color);
    text-align: right;
}

/* 标签与数值样式 */
.label-text {
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: rgba(255, 255, 255, 0.5);
}

.value-text {
    font-family: 'Consolas', monospace;
    font-weight: bold;
    color: #fff;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.3);
}

/* 进度条系统 */
.bar-wrapper {
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 3px;
    margin-top: 2px;
    overflow: hidden;
}

.bar-fill {
    height: 100%;
    width: 0%; /* 由渲染函数更新 */
    transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 0 0 10px currentColor;
}

/* 特定颜色映射 */
.color-ether { color: var(--ether-color); }
.color-samsara { color: var(--samsara-color); }
.color-entropy { color: var(--entropy-color); }

/* 轮回背景巨幕数字 */
#stat-reincarnation-bg {
    position: absolute;
    right: 5%;
    bottom: -10%;
    font-size: 80px;
    font-weight: 900;
    color: rgba(255, 255, 255, 0.03);
    pointer-events: none;
    z-index: 1;
    font-style: italic;
}

/* 词条标签云 */
.tag-container {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.tag-item {
    font-size: 9px;
    padding: 1px 5px;
    background: rgba(163, 102, 255, 0.2);
    border: 1px solid var(--ether-color);
    border-radius: 2px;
}

/* 现实崩坏：故障动画预设 */
@keyframes terminal-glitch {
    0% { clip-path: inset(80% 0 1% 0); transform: translate(-2px, 2px); }
    20% { clip-path: inset(20% 0 60% 0); transform: translate(2px, -2px); }
    40% { clip-path: inset(40% 0 40% 0); transform: translate(-2px, 0); }
    60% { clip-path: inset(0% 0 80% 0); transform: translate(2px, 2px); }
    80% { clip-path: inset(60% 0 20% 0); transform: translate(-2px, -2px); }
    100% { clip-path: inset(80% 0 1% 0); transform: translate(0); }
}

.is-glitching {
    animation: terminal-glitch 0.3s infinite;
    text-shadow: 2px 0 var(--entropy-color), -2px 0 var(--samsara-color);
}

