            ether: Number(_.get(allVars, "stat_data.世界.以太浓度", 0)),
            situation: _.get(allVars, "stat_data.世界.区域局势", "未知时空"),
            entropy: Number(_.get(allVars, "stat_data.世界.现实熵", 0))
        },

        /* 观测者核心属性 */
        char: {
            level: _.get(allVars, "stat_data.角色属性.等级", 1),
            rank: _.get(allVars, "stat_data.角色属性.位阶", 0),
            san: Number(_.get(allVars, "stat_data.角色属性.精神阈值", 100)),
            sanMax: Number(_.get(allVars, "stat_data.角色属性._精神上限", 100))
        },

        /* 因果与轮回 */
        karma: {
            energy: Number(_.get(allVars, "stat_data.因果锚点.因果能级", 0)),
            traits: _.get(allVars, "stat_data.因果锚点.进化词条", []),
            loop: _.get(allVars, "stat_data.轮回记录.当前轮回次数", 0)
        }
    };

    /* 调试用：在控制台打印读取到的数据流 */
    /* console.log("Observer Terminal Data Loaded:", data); */

    return data;
}

statusBarModules.step6:
window.renderVars = function(data) {
    /* 1. 基础文本字段渲染 */
    $('#stat-time').text(data.worldTime || 'UNKNOWN');
    $('#stat-loop-bg').text(data.loopCount || '0');
    $('#stat-loop-val').text(data.loopCount || '0');
    $('#stat-level').text(data.level || '1');

    /* 2. 位阶逻辑：数字转罗马文 */
    const romanNumerals = ['0', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];
    const rankDisplay = romanNumerals[data.rank] || data.rank || '0';
    $('#stat-rank').text(rankDisplay);

    /* 3. 动态进度条渲染 */

    /* 精神阈值（带低值变红逻辑） */
    const spiritPercent = Math.min(100, Math.max(0, (data.spirit / data.spiritMax) * 100));
    $('#stat-spirit-bar').css('width', spiritPercent + '%');
    $('#stat-spirit-val').text(Math.floor(data.spirit) + '/' + data.spiritMax);

    if (spiritPercent < 30) {
        $('#stat-spirit-bar').css('background', 'var(--color-entropy)');
        $('#stat-spirit-val').css('color', 'var(--color-entropy)');
    } else {
        $('#stat-spirit-bar').css('background', 'var(--color-ethereal)');
        $('#stat-spirit-val').css('color', 'var(--color-text)');
    }

    /* 因果能级 */
    const karmaPercent = Math.min(100, data.karmaEnergy || 0);
    $('#stat-karma-bar').css('width', karmaPercent + '%');
    $('#stat-karma-val').text(karmaPercent + '%');

    /* 现实熵 */
    const entropyPercent = Math.min(100, data.entropy || 0);
    $('#stat-entropy-bar').css('width', entropyPercent + '%');
    $('#stat-entropy-val').text(entropyPercent + '%');

    /* 4. 进化词条（数组转标签云） */
    const $tagContainer = $('#stat-tags');
    $tagContainer.empty();
    if (Array.isArray(data.evolutionTags)) {
        data.evolutionTags.forEach(function(tag) {
            if (tag) {
                $tagContainer.append('<span class="stat-tag">' + tag + '</span>');
            }
        });
    }

    /* 5. 核心视觉特效：高熵值故障化 */
    const $terminal = $('.observer-terminal');
    if (entropyPercent >= 80) {
        $terminal.addClass('is-glitching');
        /* 增加随机抖动感 */
        $terminal.css('border-color', 'var(--color-entropy)');
    } else {
        $terminal.removeClass('is-glitching');
        $terminal.css('border-color', 'rgba(100, 108, 255, 0.3)');
    }

    /* 6. 局势摘要 */
    $('#stat-situation').text(data.situation || '因果收束中...');
};

statusBarModules.step7:
/* 确保在 jQuery 加载后执行初始化 */
$(function() {
    /* 定义核心启动函数 */
    const startObserverTerminal = async () => {
        try {
            /* 关键：等待 MVU 全局变量与核心逻辑初始化完成 */
            await waitGlobalInitialized('Mvu');

            /* 定义统一的刷新动作 */
            const refreshTerminal = () => {
                /* 调用 Step 5 的读取函数 */
                const currentData = loadVars();
                /* 调用 Step 6 的渲染函数 */
                renderVars(currentData);
            };

            /* 订阅变量初始化事件：用于页面刷新或重载时恢复显示 */
            eventOn(VARIABLE_INITIALIZED, () => {
                /* console.log('[Observer Terminal] 因果锚点已就绪'); */
                refreshTerminal();
            });

            /* 订阅变量更新结束事件：在每一轮对话变量修改后触发渲染 */
            eventOn(VARIABLE_UPDATE_ENDED, () => {
                /* console.log('[Observer Terminal] 现实流向已捕捉'); */
                refreshTerminal();
            });

            /* 初始执行一次渲染，确保状态栏不留白 */
            refreshTerminal();

        } catch (error) {
            /* 捕获异常，防止脚本崩溃影响主程序 */
            console.error('[Observer Terminal Error]:', error);
        }
    };

    /* 正式挂载到生命周期 */
    startObserverTerminal();
});
